def _run_with_timeout(fn, timeout=3):
    result = {}
    error = {}

    def run():
        try:
            result['value'] = fn()
        except Exception as e:
            error['exc'] = e

    t = threading.Thread(target=run, daemon=True)
    t.start()
    t.join(timeout)
    if t.is_alive():
        return None, True  # hung
    if 'exc' in error:
        raise error['exc']
    return result.get('value'), False


